#!/usr/bin/env python
"""Assemble the LanceDB robotics blog artifact (self-contained HTML)."""

import base64
import math
from pathlib import Path

SC = Path("/tmp/claude-1000/-home-ubuntu/8bf55b6a-f750-4a10-98be-467ff5b3e97a/scratchpad")
ASSETS = Path("/home/ubuntu/work/training/examples/lerobot-lancedb-libero/assets")

# series colors via CSS vars (validated light+dark): --c-img teal, --c-mp4 blue, --c-lance orange
INK = "var(--ink)"
SUB = "var(--sub)"
GRID = "var(--line)"
MONO = "font-family:ui-monospace,SFMono-Regular,Menlo,monospace"


def b64(p, mime):
    return f"data:{mime};base64," + base64.b64encode(Path(p).read_bytes()).decode()


def svg_wrap(inner, w, h, label):
    return (f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="{label}" '
            f'style="width:100%;height:auto;display:block">{inner}</svg>')



def hbar(x, y, w, h, c, tiptxt, r=4):
    """horizontal bar: square left (baseline), rounded right (data end)"""
    w = max(w, r + 1)
    return (f'<path d="M{x},{y} h{w-r:.1f} a{r},{r} 0 0 1 {r},{r} v{h-2*r} '
            f'a{r},{r} 0 0 1 -{r},{r} h-{w-r:.1f} z" fill="{c}" data-tip="{tiptxt}"/>')


def vbar(x, y, w, h, c, tiptxt, r=4):
    """vertical bar: square bottom (baseline), rounded top (data end)"""
    h = max(h, r + 1)
    return (f'<path d="M{x},{y+h:.1f} v-{h-r:.1f} a{r},{r} 0 0 1 {r},-{r} h{w-2*r} '
            f'a{r},{r} 0 0 1 {r},{r} v{h-r:.1f} z" fill="{c}" data-tip="{tiptxt}"/>')

def tip(s):
    return s.replace('"', "&quot;")


# ── chart 2: throughput lines (log y) ─────────────────────────────────
def chart_throughput():
    data = {
        "parquet + mp4": ([415, 817, 1604], "var(--c-mp4)"),
        "Lance video": ([1162, 2296, 2920], "var(--c-lance)"),
    }
    W, H = 660, 330
    L, R, T, B = 64, 150, 36, 42
    PW, PH = W - L - R, H - T - B
    xs = [L, L + PW / 2, L + PW]
    lo, hi = 2.5, 3.6  # log10 range
    def Y(v): return T + PH - (math.log10(v) - lo) / (hi - lo) * PH
    out = []
    for e in [500, 1000, 2000, 4000]:
        y = Y(e)
        out.append(f'<line x1="{L}" y1="{y:.1f}" x2="{L+PW}" y2="{y:.1f}" stroke="{GRID}" stroke-width="1"/>')
        lbl = f"{e:,}"
        out.append(f'<text x="{L-8}" y="{y+4:.1f}" text-anchor="end" fill="{SUB}" font-size="11.5" style="{MONO}">{lbl}</text>')
    for x, wk in zip(xs, [4, 8, 16]):
        out.append(f'<text x="{x}" y="{H-16}" text-anchor="middle" fill="{SUB}" font-size="12">{wk}</text>')
    out.append(f'<text x="{L+PW/2}" y="{H-2}" text-anchor="middle" fill="{SUB}" font-size="11.5">DataLoader workers</text>')
    out.append(f'<text x="14" y="16" fill="{SUB}" font-size="11.5">samples/s (log)</text>')
    for name, (vals, c) in data.items():
        pts = " ".join(f"{x:.1f},{Y(v):.1f}" for x, v in zip(xs, vals))
        out.append(f'<polyline points="{pts}" fill="none" stroke="{c}" stroke-width="2"/>')
        for x, v in zip(xs, vals):
            out.append(f'<circle cx="{x:.1f}" cy="{Y(v):.1f}" r="4.5" fill="{c}" stroke="var(--card)" stroke-width="2" '
                       f'data-tip="{tip(name)} @ {4 if x==xs[0] else 8 if x==xs[1] else 16} workers: {v:,.0f} samples/s"/>')
        vy = Y(vals[-1])
        out.append(f'<text x="{L+PW+10}" y="{vy+4:.1f}" fill="{c}" font-size="12" font-weight="600">{name}</text>')
        out.append(f'<text x="{L+PW+10}" y="{vy+18:.1f}" fill="{SUB}" font-size="11" style="{MONO}">{vals[-1]:,.0f}/s</text>')
    return svg_wrap("".join(out), W, H, "Dataloader throughput by worker count, log scale: Lance 6121 samples/s at 16 workers vs 2547 for parquet plus mp4")


# ── chart: curated-split finetune outcome ────────────────────────────
def chart_curated():
    rows = [
        ("smolvla_base (before)", 0, "var(--c-img)"),
        ("curated split, 10k steps", 77, "var(--c-lance)"),
        ("curated split, 20k steps", 76, "var(--c-lance)"),
        ("curated split, 30k steps", 72, "var(--c-lance)"),
        ("40-task generalist, 40k", 89, "var(--c-mp4)"),
    ]
    W, H, LX = 660, 224, 250
    PW = W - LX - 70
    out = []
    for i, (name, v, c) in enumerate(rows):
        y = 14 + i * 40
        bw = max(v / 100 * PW, 3)
        out.append(f'<text x="{LX-10}" y="{y+13}" text-anchor="end" fill="{INK}" font-size="12.5">{name}</text>')
        out.append(hbar(LX, y, bw, 18, c, f"{tip(name)}: {v}% success on libero_object (100 episodes)"))
        out.append(f'<text x="{LX+bw+8:.1f}" y="{y+13}" fill="{INK}" font-size="12.5" font-weight="600" style="{MONO}">{v}%</text>')
    return svg_wrap("".join(out), W, H,
        "Curated-split finetune: 0 to 77 percent in 10k steps; later checkpoints overfit to 76 and 72; the 40-task generalist reaches 89")


# ── chart: e2e training throughput vs CPU budget ─────────────────────
def chart_cpubudget():
    budgets = ["3 vCPU/GPU", "4 vCPU/GPU\n(g4dn/g5.xl)", "8 vCPU/GPU\n(p3-class)", "26 vCPU/GPU\n(p5-class)"]
    blabels = ["3", "4 · g4dn/g5.xlarge", "8 · p3-class", "26 · p5-class/full box"]
    base = [453, 655, 1348, 2460]
    lance = [1293, 1684, 2585, 3108]
    W, H = 660, 330
    L, T, B = 64, 56, 48
    PW, PH = W - L - 20, H - T - B
    n = len(base)
    gw = PW / n
    mx = 3200.0
    out = []
    for gy in [0, 1000, 2000, 3000]:
        y = T + PH - gy / mx * PH
        out.append(f'<line x1="{L}" y1="{y:.1f}" x2="{L+PW}" y2="{y:.1f}" stroke="{GRID}" stroke-width="1"/>')
        out.append(f'<text x="{L-8}" y="{y+4:.1f}" text-anchor="end" fill="{SUB}" font-size="11.5" style="{MONO}">{gy:,}</text>')
    bw = 46
    for i in range(n):
        cx = L + gw * i + gw / 2
        for j, (v, c, name) in enumerate([(base[i], "var(--c-mp4)", "LeRobot parquet+mp4"),
                                          (lance[i], "var(--c-lance)", "Lance video")]):
            x = cx - bw - 1 + j * (bw + 2)
            bh = v / mx * PH
            y = T + PH - bh
            out.append(vbar(x, y, bw, bh, c, f"{name} @ {tip(blabels[i])} vCPU/GPU: {v:,} samples/s"))
            out.append(f'<text x="{x+bw/2:.1f}" y="{y-6:.1f}" text-anchor="middle" fill="{INK}" font-size="10.5" font-weight="600" style="{MONO}">{v:,}</text>')
        ratio = lance[i] / base[i]
        out.append(f'<text x="{cx:.1f}" y="{H-30}" text-anchor="middle" fill="{SUB}" font-size="11.5">{blabels[i]}</text>')
        out.append(f'<text x="{cx:.1f}" y="{T-8}" text-anchor="middle" fill="var(--accent)" font-size="12.5" font-weight="700" style="{MONO}">{ratio:.2f}×</text>')
    out.append(f'<text x="14" y="16" fill="{SUB}" font-size="11.5">training samples/s</text>')
    lx = L + 4
    for c, name in [("var(--c-mp4)", "LeRobot parquet+mp4"), ("var(--c-lance)", "Lance video format")]:
        out.append(f'<rect x="{lx}" y="{H-14}" width="10" height="10" rx="2" fill="{c}"/>')
        out.append(f'<text x="{lx+15}" y="{H-5}" fill="{INK}" font-size="12">{name}</text>')
        lx += 210
    return svg_wrap("".join(out), W, H, "DROID training throughput vs CPU budget: 2.85x at 3 vCPU per GPU, 2.57x at 4, 1.92x at 8, 1.26x on the full box")


# ── chart 4: success grouped bars ────────────────────────────────────
def chart_success():
    suites = ["spatial", "object", "goal", "libero_10"]
    base = [81, 88, 83, 71]
    lance = [80, 89, 77, 82]
    W, H = 660, 300
    L, T, B = 52, 34, 46
    PW, PH = W - L - 20, H - T - B
    gw = PW / 4
    out = []
    for gy in [0, 25, 50, 75, 100]:
        y = T + PH - gy / 100 * PH
        out.append(f'<line x1="{L}" y1="{y:.1f}" x2="{L+PW}" y2="{y:.1f}" stroke="{GRID}" stroke-width="1"/>')
        out.append(f'<text x="{L-8}" y="{y+4:.1f}" text-anchor="end" fill="{SUB}" font-size="11.5" style="{MONO}">{gy}</text>')
    bw = 34
    for i, s in enumerate(suites):
        cx = L + gw * i + gw / 2
        for j, (v, c, n) in enumerate([(base[i], "var(--c-img)", "base LeRobot"), (lance[i], "var(--c-lance)", "Lance")]):
            x = cx - bw - 1 + j * (bw + 2)
            bh = v / 100 * PH
            y = T + PH - bh
            out.append(vbar(x, y, bw, bh, c, f"{n} · libero_{tip(s)}: {v}% success (100 episodes)"))
            out.append(f'<text x="{x+bw/2:.1f}" y="{y-6:.1f}" text-anchor="middle" fill="{INK}" font-size="11.5" font-weight="600" style="{MONO}">{v}</text>')
        out.append(f'<text x="{cx:.1f}" y="{H-26}" text-anchor="middle" fill="{SUB}" font-size="12">{s}</text>')
    out.append(f'<text x="14" y="{T-16}" fill="{SUB}" font-size="11.5">success % · closed-loop eval, 10 eps × 10 tasks per suite</text>')
    lx = L + 4
    for c, n in [("var(--c-img)", "base LeRobot 80.8% avg"), ("var(--c-lance)", "Lance 82.0% avg")]:
        out.append(f'<rect x="{lx}" y="{H-14}" width="10" height="10" rx="2" fill="{c}"/>')
        out.append(f'<text x="{lx+15}" y="{H-5}" fill="{INK}" font-size="12">{n}</text>')
        lx += 200
    return svg_wrap("".join(out), W, H, "LIBERO success by suite: base 81/88/83/71, Lance 80/89/77/82 — parity")


# ── chart 5: n_action_steps sweep ────────────────────────────────────
def chart_nas():
    pts = [(1, 72), (2, 23), (3, 25), (5, 50), (10, 16), (25, 1)]
    W, H = 660, 250
    L, T, B, R = 52, 26, 44, 22
    PW, PH = W - L - R, H - T - B
    def X(v): return L + (math.log10(v)) / math.log10(25) * PW
    def Y(v): return T + PH - v / 85 * PH
    out = []
    for gy in [0, 20, 40, 60, 80]:
        y = Y(gy)
        out.append(f'<line x1="{L}" y1="{y:.1f}" x2="{L+PW}" y2="{y:.1f}" stroke="{GRID}" stroke-width="1"/>')
        out.append(f'<text x="{L-8}" y="{y+4:.1f}" text-anchor="end" fill="{SUB}" font-size="11.5" style="{MONO}">{gy}</text>')
    poly = " ".join(f"{X(a):.1f},{Y(b):.1f}" for a, b in pts)
    out.append(f'<polyline points="{poly}" fill="none" stroke="var(--c-lance)" stroke-width="2"/>')
    for a, b in pts:
        out.append(f'<circle cx="{X(a):.1f}" cy="{Y(b):.1f}" r="4.5" fill="var(--c-lance)" stroke="var(--card)" stroke-width="2" '
                   f'data-tip="n_action_steps={a}: {b}% success on libero_object"/>')
        anchor, dx = ("start", 10) if a == 1 else ("middle", 0)
        out.append(f'<text x="{X(a)+dx:.1f}" y="{Y(b)-10:.1f}" text-anchor="{anchor}" fill="{INK}" font-size="11.5" font-weight="600" style="{MONO}">{b}</text>')
        out.append(f'<text x="{X(a):.1f}" y="{H-24}" text-anchor="middle" fill="{SUB}" font-size="12" style="{MONO}">{a}</text>')
    out.append(f'<text x="{L+PW/2}" y="{H-4}" text-anchor="middle" fill="{SUB}" font-size="11.5">n_action_steps — how much of the 50-step action chunk runs open-loop (log)</text>')
    out.append(f'<text x="14" y="{T-10}" fill="{SUB}" font-size="11.5">success % · same checkpoint, libero_object</text>')
    return svg_wrap("".join(out), W, H, "Eval sensitivity: 72% at n_action_steps 1 falling to 1% at 25 for the same checkpoint")


